import{_ as c,C as l,o as i,c as n,ak as a,E as o,j as d,a as r}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"Kbd 键盘按键","description":"","frontmatter":{},"headers":[],"relativePath":"components/kbd.md","filePath":"components/kbd.md","lastUpdated":1789920491000}'),h={name:"components/kbd.md"};function s(b,t,u,p,k,f){const e=l("XhDemo");return i(),n("div",null,[t[0]||(t[0]=a('<h1 id="kbd-键盘按键" tabindex="-1">Kbd 键盘按键 <a class="header-anchor" href="#kbd-键盘按键" aria-label="Permalink to &quot;Kbd 键盘按键&quot;">​</a></h1><p>显示单个键或快捷键组合；需要实际响应按键时，显式开启 <code>register</code>。<code>Mod</code> 在 Mac 上显示为 ⌘，其他平台显示为 Ctrl。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/kbd" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/kbd.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/kbd" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/kbd" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/kbd.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>单键与组合键使用同一组件</p>',5)),o(e,{src:"kbd/01-basic"}),t[1]||(t[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;kbd&quot;</code>：<strong><code>root</code></strong> · <code>key</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="外观" tabindex="-1">外观 <a class="header-anchor" href="#外观" aria-label="Permalink to &quot;外观&quot;">​</a></h3><p>default 使用中性底，light 保持透明</p>',6)),o(e,{src:"kbd/02-variant"}),t[2]||(t[2]=d("h3",{id:"平台键名",tabindex:"-1"},[r("平台键名 "),d("a",{class:"header-anchor",href:"#平台键名","aria-label":'Permalink to "平台键名"'},"​")],-1)),t[3]||(t[3]=d("p",null,"常用按键与跨平台组合由 Headless 统一格式化",-1)),o(e,{src:"kbd/03-special"}),t[4]||(t[4]=d("h3",{id:"快捷键注册",tabindex:"-1"},[r("快捷键注册 "),d("a",{class:"header-anchor",href:"#快捷键注册","aria-label":'Permalink to "快捷键注册"'},"​")],-1)),t[5]||(t[5]=d("p",null,"可见提示显式开启 register 后响应按键",-1)),o(e,{src:"kbd/04-inline"}),t[6]||(t[6]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>表示单个键或同时按下的组合键。</li><li>在说明文字或操作旁提示键盘输入。</li><li>让可见的快捷键提示同时承担注册行为。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>代码和命令使用<a href="./code-view">代码视图</a>。</li><li>只注册、不需要任何可见提示的全局命令，应放在应用自己的命令系统中。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>单键和组合键都只渲染一个原生 <code>kbd</code> 表面。</li><li>组合键名之间保留 4px 间隙，不显示加号。</li><li>平台键名由 Headless 统一格式化。</li><li>默认不监听；<code>register</code> 开启后支持全局或局部 <code>target</code>、动态 <code>enabled</code> 与 <code>preventDefault</code>。</li><li>固定使用 24px 高度；<code>default</code> 使用中性底，<code>light</code> 保持透明。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>可放在按钮、菜单项和说明文字中。</li><li><code>keys</code> 的顺序就是视觉顺序；RTL 文本中也保持物理键位顺序。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>跨平台快捷键使用 <code>Mod</code>。</li><li>同时按下的键放在同一份 <code>keys</code> 中，不要手工拼接加号或多个 Kbd。</li><li>只有确实需要监听时才开启 <code>register</code>，避免展示文字意外接管浏览器快捷键。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>不要用 Kbd 代替按钮或菜单项。</li><li>不要把依次输入的按键序列当成同时按下的组合。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-kbd&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhKbd</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/kbd.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>boolean</code></td><td></td><td>已注册的监听是否生效，默认 true。</td></tr><tr><td><code>keys</code></td><td><code>string[]</code></td><td>是</td><td>单键或组合键，例如 [&#39;Escape&#39;]、[&#39;Mod&#39;, &#39;K&#39;]。</td></tr><tr><td><code>onHotKey</code></td><td><code>(details: KbdTriggerDetails) =&gt; void</code></td><td></td><td>已注册组合被按下时触发。</td></tr><tr><td><code>platform</code></td><td><code>KbdPlatform</code></td><td></td><td>平台键名；auto 在适配器探测前按非 Mac 输出。</td></tr><tr><td><code>preventDefault</code></td><td><code>boolean</code></td><td></td><td>命中时是否阻止浏览器默认动作，默认 true。</td></tr><tr><td><code>register</code></td><td><code>boolean</code></td><td></td><td>是否注册快捷键监听，默认 false。</td></tr><tr><td><code>target</code></td><td><code>KbdTarget</code></td><td></td><td>监听目标，默认 document；局部监听传入返回 EventTarget 的函数。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;KbdTranslations&gt;</code></td><td></td><td>逐键名称和整组读屏文案。</td></tr><tr><td><code>variant</code></td><td><code>KbdVariant</code></td><td></td><td>视觉外观，默认 default。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>hot-key</code></td><td><code>KbdTriggerDetails</code></td><td>组合被按下；detail 为 <code>{ keys: string[], event: KeyboardEvent }</code></td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>segments</code></td><td><code>readonly HotkeySegment[]</code></td><td></td></tr><tr><td><code>platform</code></td><td><code>KbdResolvedPlatform</code></td><td></td></tr><tr><td><code>register</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>enabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>target</code></td><td><code>KbdTarget</code></td><td></td></tr><tr><td><code>resolveTarget</code></td><td><code>(documentTarget: EventTarget | null) =&gt; EventTarget | null</code></td><td></td></tr><tr><td><code>matches</code></td><td><code>(event: KeyboardEvent) =&gt; boolean</code></td><td></td></tr><tr><td><code>handleKeyDown</code></td><td><code>(event: KeyboardEvent) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getKeyProps</code></td><td><code>(props: KbdKeyProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/TR/uievents/#event-type-keydown" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>keys 指定的组合</code></td><td>register 开启、enabled 未关，且不在输入法组合期</td><td>触发 onHotKey；preventDefault 开启（默认）时同时拦下浏览器默认动作</td></tr><tr><td><code>keys 指定的组合</code></td><td>组合里没有 Ctrl / Meta / Alt，且按键落在输入区里</td><td>不触发也不拦截，输入优先</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations?.hotkey?.(names)</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;img&#39;</td></tr><tr><td><code>key</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根元素取 <code>role=&quot;img&quot;</code> 并通过 <code>aria-label</code> 把整组朗读一次；原生 <code>kbd</code> 是 generic 角色，直接写 <code>aria-label</code> 会被读屏忽略。视觉键名不重复进入无障碍树。</li><li>普通字符快捷键落在输入区时不会接管输入；带 Ctrl、Meta 或 Alt 的命令组合仍可响应。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/kbd.css</code> 使用 <code>[data-scope=&quot;kbd&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-platform</code></td><td>resolveKbdPlatform(props.platform)</td></tr><tr><td><code>root</code></td><td><code>data-register</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>key</code></td><td><code>data-key</code></td><td>segmentOf(value)?.key</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-kbd-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-bg-subtle</code></td><td>kbd 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-kbd-border</code></td><td><code>root</code></td><td><code>border</code></td><td><code>default</code></td><td><code>transparent</code></td><td>kbd 的 root 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-kbd-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>kbd 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-fg-disabled</code></td><td><code>root</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-disabled</code></td><td>kbd 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-font</code></td><td><code>root</code></td><td><code>font-family</code></td><td><code>default</code></td><td><code>inherit</code></td><td>kbd 的 root 部件 font-family 覆盖槽。</td></tr><tr><td><code>--xh-kbd-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-caption-size</code></td><td>kbd 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-font-weight</code></td><td><code>root</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-medium</code></td><td>kbd 的 root 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-kbd-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>kbd 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-kbd-h</code></td><td><code>root</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-space-6</code></td><td>kbd 的 root 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-min-w</code></td><td><code>root</code></td><td><code>min-inline-size</code></td><td><code>default</code></td><td><code>--xh-space-6</code></td><td>kbd 的 root 部件 min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-px</code></td><td><code>root</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>kbd 的 root 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-kbd-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>kbd 的 root 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',46))])}const x=c(h,[["render",s]]);export{m as __pageData,x as default};
